-- contract: partial, on `kind = 'perpanjangan_tpu'` only. No release before ticket 48 writes a Perpanjangan TPU order (the kind is only listed in the schema's enum; nothing inserts it), so the index matches no row the running release wrote or can write and cannot fail on a database still being written. It is here because it is the race-safe guard against two open renewals of one Makam TPU, i.e. a double charge (ticket 48 review), behind `placePerpanjanganTpu`'s `sudah_dipesan` refusal.
CREATE UNIQUE INDEX "pengurusan_tpu_perpanjangan_terbuka_idx" ON "pengurusan_tpu" USING btree ("makam_tpu_id") WHERE "pengurusan_tpu"."kind" = 'perpanjangan_tpu' and "pengurusan_tpu"."status" not in ('ditolak', 'dibatalkan', 'iptm_terbit');